let coreRouteTargets;async function render(){await refreshSession();const p=location.pathname;coreRouteTargets||=await(await fetch('/static/core-route-targets.json')).json();if(coreRouteTargets[p]){go(coreRouteTargets[p],true);return}document.title='OneDrive';if(p==='/my'&&new URLSearchParams(location.search).get('sort')==='size'){go('/largest',true);return}if(p==='/logout'){await api('/api/auth/logout','POST',{});location.assign('/');return}if(['/login','/signup','/recover','/verify'].includes(p)){if(p==='/verify'&&!authUI.purpose){const purpose=new URLSearchParams(location.search).get('purpose');if(['registration','password-reset','passwordless-signin'].includes(purpose)){authUI={flow:purpose==='registration'?'register':purpose==='password-reset'?'recover':'login',step:'code',purpose};saveAuthUI()}}renderAuth();return}if(S.account){S.prefs=await api('/api/preferences');S.storage=await api('/api/storage');document.body.classList.toggle('dark',S.prefs.theme==='dark')}else document.body.classList.remove('dark');if(p.startsWith('/boundary/')){await renderBoundary(p.split('/')[2]);return}if(p.startsWith('/s/')){await renderSharedPage();return}if(p==='/plans'){location.assign('/marketing/onedrive-plans-and-pricing');return}if(p==='/privacy'||p==='/terms'||p.startsWith('/help')){await renderHelp(p);return}if(p.startsWith('/checkout/offer-')){await renderCheckout();return}if(!S.account){location.assign('/login?next='+encodeURIComponent(p));return}if(p.startsWith('/settings'))await renderSettings();else if(p.startsWith('/photos'))await renderPhotos();else if(p==='/largest')await renderLargest();else if(p.startsWith('/file/'))await renderEditor(p.split('/')[2]);else if(p.startsWith('/account'))await renderAccount();else if(p.startsWith('/checkout'))await renderCheckout();else await renderFiles()}
async function renderAccount(){await window.renderAccountPage()}
async function renderHelp(p){const mapped=await(await fetch('/static/help-targets.json')).json();if(mapped[p]){go(location.hash?mapped[p].split('#')[0]+location.hash:mapped[p]);return}const name={'/help':'OneDrive 帮助和学习','/help/restore':'Restore files deleted from your OneDrive','/help/import':'导入云照片和文件','/help/photos':'组织和查找照片','/privacy':'Privacy and cookies','/terms':'Terms of use'}[p]||'OneDrive 帮助';let articles={};try{articles=await (await fetch('/static/help.json')).json()}catch{}const d=articles[p];$('#app').innerHTML=topbar()+`<main class="boundary"><h1>${esc(d?.title||name)}</h1><article class="help-article">${d?d.html:`<p>该关联页面尚未完成原站取证。</p>`}</article><footer>${link('OneDrive 帮助和学习','/help')}${link('返回 OneDrive','/')}</footer></main>`;window.initializeHelp?.($('.help-article'))}
async function renderCheckout(){const offers=await(await fetch('/static/offers.json')).json(),id=new URLSearchParams(location.search).get('offer')||location.pathname.split('/').at(-1).replace('offer-',''),offer=offers[id];let articles={};try{articles=await(await fetch('/static/help.json')).json()}catch{}const captured=articles['/checkout/offer-'+id];if(!captured&&!S.account){go('/login?next='+encodeURIComponent(location.pathname+location.search),true);return}$('#app').innerHTML=topbar()+`<main class="boundary"><h1>${esc(offer?.title||'Microsoft 365')}</h1><article class="help-article">${captured?captured.html:`<p>${esc(offer?.label||'计划和升级')}</p>`}</article><p role="status">此购买入口的结算步骤尚未取得有效原站证据，当前无法完成购买。</p><footer>${link('查看计划','/plans')}${link('返回 OneDrive','/')}</footer></main>`;window.initializeHelp?.($('.help-article'))}

