 if(a==='editor-find'||a==='editor-replace'){modal(a==='editor-find'?'Find':'Replace',`<form id="find-form" data-replace="${a==='editor-replace'}"><label>Find</label><input name="find" required>${a==='editor-replace'?'<label>Replace with</label><input name="replace">':''}<footer><button class="primary">${a==='editor-find'?'Find':'Replace all'}</button></footer></form>`);return}
